-- Retail Insight production import snapshot from the configured retail_app database.
-- Personal identifiers, credentials, sessions, OTPs, support conversations, audit trails, and notifications are sanitized/omitted.
-- Recreate live owner/staff credentials after import; no source password is carried into this dump.
SET NAMES utf8mb4;
USE retail_app;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS `app_settings` (
  `scope_type` enum('USER','PLATFORM') COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `settings` json NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`scope_type`,`scope_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `audit_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `username` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organization_id` bigint DEFAULT NULL,
  `branch_id` int unsigned DEFAULT NULL,
  `event_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BLOCKED',
  `details` json DEFAULT NULL,
  `request_snippet` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unlocked_by` int unsigned DEFAULT NULL,
  `unlocked_at` datetime DEFAULT NULL,
  `unlock_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_audit_user` (`user_id`),
  KEY `idx_audit_org` (`organization_id`),
  KEY `idx_audit_event` (`event_type`),
  KEY `idx_audit_created` (`created_at`),
  KEY `idx_audit_severity` (`severity`),
  KEY `idx_audit_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `auth_sessions` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `organization_id` int unsigned DEFAULT NULL,
  `user_id` int unsigned NOT NULL,
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `organization_id` (`organization_id`,`user_id`),
  KEY `expires_at` (`expires_at`),
  CONSTRAINT `auth_sessions_ibfk_1` FOREIGN KEY (`organization_id`, `user_id`) REFERENCES `users` (`organization_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `branches` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `catalog_mode` enum('SHARED','INDEPENDENT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SHARED',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `pos_layout_mode` enum('OWNER_MODE','CASHIER_MODE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OWNER_MODE',
  `manager_can_change_pos_mode` tinyint(1) NOT NULL DEFAULT '0',
  `bank_bin` varchar(12) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_number` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `static_qr_url` mediumtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `branch_tenant` (`organization_id`,`id`),
  CONSTRAINT `branches_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=426 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `branch_id` int unsigned DEFAULT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `branch_id_scope` int unsigned GENERATED ALWAYS AS (coalesce(`branch_id`,0)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `category_tenant` (`organization_id`,`id`),
  UNIQUE KEY `category_name_scope` (`organization_id`,`branch_id_scope`,`name`),
  KEY `category_branch` (`organization_id`,`branch_id`),
  CONSTRAINT `categories_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_categories_branch` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`)
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `customers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_tenant` (`organization_id`,`id`),
  KEY `customer_search` (`organization_id`,`phone`,`name`),
  CONSTRAINT `customers_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `inventory_balances` (
  `organization_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `product_id` int unsigned NOT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `average_cost` decimal(16,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`organization_id`,`branch_id`,`product_id`),
  KEY `organization_id` (`organization_id`,`product_id`),
  CONSTRAINT `inventory_balances_ibfk_1` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`),
  CONSTRAINT `inventory_balances_ibfk_2` FOREIGN KEY (`organization_id`, `product_id`) REFERENCES `products` (`organization_id`, `id`),
  CONSTRAINT `inventory_balances_chk_1` CHECK ((`quantity` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `inventory_movements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `product_id` int unsigned NOT NULL,
  `document_id` bigint unsigned NOT NULL,
  `quantity_delta` int NOT NULL,
  `balance_after` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `movement_type` enum('RECEIPT','SALE','ADJUSTMENT','TRANSFER','RETURN') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `movement_period` (`organization_id`,`branch_id`,`created_at`),
  KEY `organization_id` (`organization_id`,`product_id`),
  KEY `organization_id_2` (`organization_id`,`document_id`),
  CONSTRAINT `inventory_movements_ibfk_1` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`),
  CONSTRAINT `inventory_movements_ibfk_2` FOREIGN KEY (`organization_id`, `product_id`) REFERENCES `products` (`organization_id`, `id`),
  CONSTRAINT `inventory_movements_ibfk_3` FOREIGN KEY (`organization_id`, `document_id`) REFERENCES `stock_documents` (`organization_id`, `id`),
  CONSTRAINT `inventory_movements_chk_1` CHECK ((`balance_after` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=1393 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `notification_digests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `branch_id` int unsigned DEFAULT NULL,
  `digest_type` enum('DAILY','MONTHLY') COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_key` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` json NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `digest_user_period` (`organization_id`,`user_id`,`digest_type`,`period_key`,`branch_id`),
  KEY `idx_digest_user` (`organization_id`,`user_id`,`created_at`),
  KEY `organization_id` (`organization_id`,`branch_id`),
  CONSTRAINT `notification_digests_ibfk_1` FOREIGN KEY (`organization_id`, `user_id`) REFERENCES `users` (`organization_id`, `id`) ON DELETE CASCADE,
  CONSTRAINT `notification_digests_ibfk_2` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `notification_reads` (
  `organization_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `notification_id` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `read_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`organization_id`,`user_id`,`notification_id`),
  KEY `idx_notification_reads_user` (`organization_id`,`user_id`,`read_at`),
  CONSTRAINT `fk_notification_reads_user` FOREIGN KEY (`organization_id`, `user_id`) REFERENCES `users` (`organization_id`, `id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `notifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `recipient_user_id` int unsigned NOT NULL,
  `organization_id` int unsigned DEFAULT NULL,
  `type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metadata` json DEFAULT NULL,
  `read_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_notifications_recipient` (`recipient_user_id`,`read_at`,`created_at`),
  KEY `idx_notifications_type` (`type`,`created_at`),
  KEY `fk_notifications_org` (`organization_id`),
  CONSTRAINT `fk_notifications_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notifications_recipient` FOREIGN KEY (`recipient_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `organization_dataset_access` (
  `organization_id` int unsigned NOT NULL,
  `dataset_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`organization_id`,`dataset_id`),
  CONSTRAINT `organization_dataset_access_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `organizations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plan` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'basic',
  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=425 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `password_otps` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_expires` (`user_id`,`expires_at`),
  CONSTRAINT `fk_password_otps_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `platform_notification_digests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `digest_type` enum('DAILY','MONTHLY') COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_key` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` json NOT NULL,
  `read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `platform_digest_user_period` (`user_id`,`digest_type`,`period_key`),
  KEY `idx_platform_digest_user` (`user_id`,`created_at`),
  CONSTRAINT `platform_notification_digests_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `products` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `branch_id` int unsigned DEFAULT NULL,
  `category_id` int unsigned DEFAULT NULL,
  `sku` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sale_price` decimal(16,2) NOT NULL,
  `cost_price` decimal(16,2) DEFAULT NULL,
  `attributes` json DEFAULT NULL,
  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `branch_id_scope` int unsigned GENERATED ALWAYS AS (coalesce(`branch_id`,0)) STORED,
  `image_url` mediumtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_tenant` (`organization_id`,`id`),
  UNIQUE KEY `product_sku_scope` (`organization_id`,`branch_id_scope`,`sku`),
  KEY `organization_id` (`organization_id`,`category_id`),
  KEY `product_branch` (`organization_id`,`branch_id`),
  CONSTRAINT `fk_products_branch` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`organization_id`, `category_id`) REFERENCES `categories` (`organization_id`, `id`),
  CONSTRAINT `products_chk_1` CHECK ((`sale_price` >= 0)),
  CONSTRAINT `products_chk_2` CHECK (((`cost_price` is null) or (`cost_price` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=768 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `registration_otps` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_reg_email_expires` (`email`,`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=232 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `sale_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `document_id` bigint unsigned NOT NULL,
  `method` enum('CASH','BANK_TRANSFER') COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_type` enum('SALE','REFUND') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SALE',
  `status` enum('PAID','PENDING','WAITING_PAYMENT','FAILED','REFUNDED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(16,2) NOT NULL,
  `received_amount` decimal(16,2) DEFAULT NULL,
  `change_amount` decimal(16,2) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `confirmed_by` int unsigned DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_sale_payment_confirmer` (`organization_id`,`confirmed_by`),
  KEY `payment_document_type` (`organization_id`,`document_id`,`payment_type`),
  CONSTRAINT `fk_sale_payment_confirmer` FOREIGN KEY (`organization_id`, `confirmed_by`) REFERENCES `users` (`organization_id`, `id`),
  CONSTRAINT `sale_payments_ibfk_1` FOREIGN KEY (`organization_id`, `document_id`) REFERENCES `stock_documents` (`organization_id`, `id`),
  CONSTRAINT `sale_payments_chk_2` CHECK (((`received_amount` is null) or (`received_amount` >= 0))),
  CONSTRAINT `sale_payments_chk_3` CHECK (((`change_amount` is null) or (`change_amount` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=393 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `schema_migrations` (
  `version` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `applied_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `security_notifications` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `username` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organization_id` int unsigned DEFAULT NULL,
  `audit_log_id` bigint DEFAULT NULL,
  `event_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HIGH',
  `is_read` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sec_notif_unread` (`is_read`,`created_at`),
  KEY `idx_sec_notif_severity` (`severity`)
) ENGINE=InnoDB AUTO_INCREMENT=135 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `stock_document_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `document_id` bigint unsigned NOT NULL,
  `product_id` int unsigned NOT NULL,
  `sku` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_name` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` int NOT NULL,
  `system_quantity` int DEFAULT NULL,
  `actual_quantity` int DEFAULT NULL,
  `variance` int DEFAULT NULL,
  `unit_price` decimal(16,2) NOT NULL,
  `discount_type` enum('PERCENT','FIXED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discount_value` decimal(16,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `line_total` decimal(16,2) NOT NULL DEFAULT '0.00',
  `unit_cost` decimal(16,2) DEFAULT NULL,
  `returned_quantity` decimal(16,3) NOT NULL DEFAULT '0.000',
  PRIMARY KEY (`id`),
  UNIQUE KEY `document_product` (`document_id`,`product_id`),
  KEY `organization_id` (`organization_id`,`document_id`),
  KEY `organization_id_2` (`organization_id`,`product_id`),
  CONSTRAINT `stock_document_items_ibfk_1` FOREIGN KEY (`organization_id`, `document_id`) REFERENCES `stock_documents` (`organization_id`, `id`),
  CONSTRAINT `stock_document_items_ibfk_2` FOREIGN KEY (`organization_id`, `product_id`) REFERENCES `products` (`organization_id`, `id`),
  CONSTRAINT `stock_document_items_chk_1` CHECK ((`quantity` >= 0)),
  CONSTRAINT `stock_document_items_chk_2` CHECK ((`unit_price` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=1381 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `stock_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `destination_branch_id` int unsigned DEFAULT NULL,
  `type` enum('RECEIPT','SALE','ADJUSTMENT','TRANSFER') COLLATE utf8mb4_unicode_ci NOT NULL,
  `request_key` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `performed_by` int unsigned NOT NULL,
  `total` decimal(16,2) NOT NULL,
  `note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `customer_id` bigint unsigned DEFAULT NULL,
  `subtotal` decimal(16,2) NOT NULL DEFAULT '0.00',
  `item_discount_total` decimal(16,2) NOT NULL DEFAULT '0.00',
  `order_discount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `payment_method` enum('CASH','BANK_TRANSFER') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` enum('PAID','WAITING_PAYMENT','FAILED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cash_received` decimal(16,2) DEFAULT NULL,
  `change_due` decimal(16,2) DEFAULT NULL,
  `order_status` enum('OPEN','COMPLETED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'COMPLETED',
  `client_created_at` datetime(3) DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `return_status` enum('NONE','PARTIAL_RETURNED','FULL_RETURNED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `returned_amount` decimal(16,2) NOT NULL DEFAULT '0.00',
  `returned_cost` decimal(16,2) NOT NULL DEFAULT '0.00',
  `return_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `returned_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `document_tenant` (`organization_id`,`id`),
  UNIQUE KEY `document_request` (`organization_id`,`type`,`request_key`),
  KEY `document_period` (`organization_id`,`created_at`,`branch_id`),
  KEY `organization_id_2` (`organization_id`,`performed_by`),
  KEY `fk_document_customer` (`organization_id`,`customer_id`),
  KEY `fk_stock_docs_dest_branch` (`organization_id`,`destination_branch_id`),
  KEY `idx_sale_open` (`organization_id`,`branch_id`,`type`,`order_status`,`created_at`),
  CONSTRAINT `fk_document_customer` FOREIGN KEY (`organization_id`, `customer_id`) REFERENCES `customers` (`organization_id`, `id`),
  CONSTRAINT `fk_stock_docs_dest_branch` FOREIGN KEY (`organization_id`, `destination_branch_id`) REFERENCES `branches` (`organization_id`, `id`),
  CONSTRAINT `stock_documents_ibfk_1` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`),
  CONSTRAINT `stock_documents_ibfk_2` FOREIGN KEY (`organization_id`, `performed_by`) REFERENCES `users` (`organization_id`, `id`),
  CONSTRAINT `stock_documents_chk_1` CHECK ((`total` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=637 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `support_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `thread_id` bigint unsigned NOT NULL,
  `sender_user_id` int unsigned NOT NULL,
  `sender_role` enum('USER','ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `message_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_recalled` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_support_messages_thread` (`thread_id`,`id`),
  KEY `fk_support_messages_sender` (`sender_user_id`),
  KEY `idx_support_messages_type` (`thread_id`,`message_type`,`id`),
  CONSTRAINT `fk_support_messages_sender` FOREIGN KEY (`sender_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_support_messages_thread` FOREIGN KEY (`thread_id`) REFERENCES `support_threads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `support_threads` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `thread_type` enum('ADMIN_SUPPORT','INTERNAL_CHAT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ADMIN_SUPPORT',
  `user_id` int unsigned NOT NULL,
  `recipient_user_id` int unsigned DEFAULT NULL,
  `recipient_user_key` int unsigned NOT NULL DEFAULT '0',
  `subject` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hỗ trợ vận hành',
  `category` enum('GENERAL','WEB_DESIGN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL',
  `web_request_status` enum('NEW','IN_PROGRESS','COMPLETED') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `web_form_submitted` tinyint(1) NOT NULL DEFAULT '0',
  `web_form_reminder_sent` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('OPEN','IN_PROGRESS','RESOLVED','CLOSED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `unread_admin_count` int unsigned NOT NULL DEFAULT '0',
  `unread_user_count` int unsigned NOT NULL DEFAULT '0',
  `last_message_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_support_thread_conversation` (`organization_id`,`thread_type`,`user_id`,`recipient_user_key`),
  KEY `idx_support_threads_activity` (`last_message_at`,`id`),
  KEY `idx_support_threads_org` (`organization_id`,`last_message_at`),
  KEY `idx_support_thread_user` (`user_id`),
  KEY `idx_support_threads_recipient` (`recipient_user_id`,`last_message_at`),
  KEY `idx_support_threads_type_category_activity` (`thread_type`,`category`,`last_message_at`),
  CONSTRAINT `fk_support_threads_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_support_threads_recipient` FOREIGN KEY (`recipient_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_support_threads_user_v2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=218 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `support_tickets` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned DEFAULT NULL,
  `user_id` int unsigned NOT NULL,
  `category` enum('TECH_SUPPORT','BUG_REPORT','ONLINE_WEB_REQUEST','FEATURE_REQUEST') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TECH_SUPPORT',
  `subject` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_info` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('OPEN','IN_PROGRESS','RESOLVED','CLOSED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `admin_note` text COLLATE utf8mb4_unicode_ci,
  `support_thread_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `idx_tickets_org` (`organization_id`),
  KEY `idx_tickets_status` (`status`),
  KEY `idx_support_ticket_thread` (`support_thread_id`),
  CONSTRAINT `fk_support_ticket_thread` FOREIGN KEY (`support_thread_id`) REFERENCES `support_threads` (`id`) ON DELETE SET NULL,
  CONSTRAINT `support_tickets_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `support_tickets_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `user_branch_roles` (
  `organization_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `role` enum('OWNER','MANAGER','INVENTORY','CASHIER') COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`user_id`,`branch_id`),
  KEY `organization_id` (`organization_id`,`user_id`),
  KEY `organization_id_2` (`organization_id`,`branch_id`),
  CONSTRAINT `user_branch_roles_ibfk_1` FOREIGN KEY (`organization_id`, `user_id`) REFERENCES `users` (`organization_id`, `id`),
  CONSTRAINT `user_branch_roles_ibfk_2` FOREIGN KEY (`organization_id`, `branch_id`) REFERENCES `branches` (`organization_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned DEFAULT NULL,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `full_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('OWNER','MANAGER','INVENTORY','CASHIER','PLATFORM_ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CASHIER',
  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `locked_until` datetime DEFAULT NULL,
  `lock_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `locked_at` datetime DEFAULT NULL,
  `unlock_request_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unlock_requested_at` datetime DEFAULT NULL,
  `avatar_url` mediumtext COLLATE utf8mb4_unicode_ci,
  `bio` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `user_tenant` (`organization_id`,`id`),
  KEY `idx_users_locked` (`locked_until`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=954 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

